class ExpressionEvaluator:
    def __init__(self, expr: str):
        self.expr = expr.replace(' ', '')
        self.pos = 0

    def parse_expression(self) -> float:
        value = self.parse_term()
        while self.pos < len(self.expr):
            if self.expr[self.pos] == '+':
                self.pos += 1
                value += self.parse_term()
            elif self.expr[self.pos] == '-':
                self.pos += 1
                value -= self.parse_term()
            else:
                break
        return value

    def parse_term(self) -> float:
        value = self.parse_factor()
        while self.pos < len(self.expr):
            if self.expr[self.pos] == '*':
                self.pos += 1
                value *= self.parse_factor()
            elif self.expr[self.pos] == '/':
                self.pos += 1
                value /= self.parse_factor()
            else:
                break
        return value

    def parse_factor(self) -> float:
        if self.expr[self.pos] == '(':
            self.pos += 1
            value = self.parse_expression()
            self.pos += 1  # Skip ')'
            return value
        return self.parse_number()

    def parse_number(self) -> float:
        start_pos = self.pos
        while (self.pos < len(self.expr) and 
               (self.expr[self.pos].isdigit() or self.expr[self.pos] == '.')):
            self.pos += 1
        return float(self.expr[start_pos:self.pos])


def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using a recursive descent parser
