class Evaluator:
    def __init__(self, expr: str):
        self.expr = expr
        self.position = 0
        self.current_char = self.expr[self.position] if self.expr else None

    def advance(self):
        self.position += 1
        if self.position < len(self.expr):
            self.current_char = self.expr[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.expr()
            self.advance()  # Skip ')'
            return result
        else:
            return self.number()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            operation = self.current_char
            self.advance()
            if operation == '*':
                result *= self.factor()
            elif operation == '/':
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            operation = self.current_char
            self.advance()
            if operation == '+':
                result += self.term()
            elif operation == '-':
                result -= self.term()
        return result

def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression with +, -, *, /, 
    parentheses and floating-point numbers using a recursive descent parser.
    """
    evaluator = Evaluator(expr)
    evaluator.skip_whitespace()
    result = evaluator.expr()
    return result

